// Base exception with status code
export abstract class BusinessLogicException extends Error {
  abstract readonly statusCode: number;
}

// Concrete exceptions with correct HTTP codes
export class InvalidTokenException
    extends BusinessLogicException {
  readonly statusCode = 401;
  constructor() {
    super('Invalid or expired booking token');
  }
}

export class OrderAlreadyDoneException
