async createOrder(
  orderLine: OrderLineCTO[],
  bookingToken: string
): Promise<Order> {
  return await this.connection.transaction(
    async (entityManager) => {
      // Token validation (same as before)
      // ...

      // Save order within transaction
      let newOrder = await entityManager.save(
        Order,
        new Order({ bookingId, invitedGuestId })
      );

      // Save all order lines atomically
      const lines = orderLine.map(elem => {
        const line = plainToClass(OrderLine, elem.orderLine);
        line.ingredients = elem.extras;
        line.orderId = newOrder.id;
        return line;
      });
      await entityManager.save(OrderLine, lines);

      // Reload with relations
      newOrder = await entityManager.findOne(Order, {
        where: { id: newOrder.id },
        relations: [
          'orderLines',
          'orderLines.dish',
          'orderLines.ingredients'
        ],
      });

      if (this.orderMailer) {
        this.orderMailer.sendOrderEmail(
          booking, newOrder!, this.getTotalPrice(newOrder!)
        );
      }
      return newOrder!;
  });
}

